<?php require __DIR__.'/config/config.php';require __DIR__.'/config/helpers.php';$id=(int)($_GET['id']??0);$q=$pdo->prepare("SELECT h.*, (SELECT ROUND(AVG(note),1) FROM reviews WHERE hotel_id=h.id) note FROM hotels h WHERE h.id=? AND h.statut='valide'");$q->execute([$id]);$hotel=$q->fetch();if(!$hotel){http_response_code(404);$pageTitle='Hôtel introuvable';require __DIR__.'/includes/header.php';echo '<div class="container section"><h1>Hôtel introuvable</h1><a href="index.php">Retour à l’accueil</a></div>';require __DIR__.'/includes/footer.php';exit;}$q=$pdo->prepare('SELECT * FROM rooms WHERE hotel_id=? AND actif=1 ORDER BY prix_nuit');$q->execute([$id]);$rooms=$q->fetchAll();$q=$pdo->prepare('SELECT p.fichier FROM hotel_photos p WHERE p.hotel_id=? ORDER BY p.principale DESC,p.id DESC LIMIT 3');$q->execute([$id]);$photos=$q->fetchAll();$q=$pdo->prepare('SELECT a.nom FROM amenities a JOIN hotel_amenities ha ON ha.amenity_id=a.id WHERE ha.hotel_id=?');$q->execute([$id]);$amenities=$q->fetchAll();$q=$pdo->prepare('SELECT rv.*,u.prenom FROM reviews rv JOIN users u ON u.id=rv.user_id WHERE rv.hotel_id=? ORDER BY rv.created_at DESC LIMIT 10');$q->execute([$id]);$reviews=$q->fetchAll();$pageTitle=$hotel['nom'];require __DIR__.'/includes/header.php';?><section class="detail-hero"><div class="container"><a class="text-link" href="index.php">← Retour aux hôtels</a><h1 class="mt-3"><?=e($hotel['nom'])?></h1><p class="muted">⌖ <?=e($hotel['adresse']?$hotel['adresse'].', ':'')?><?=e($hotel['commune']?$hotel['commune'].', ':'')?><?=e($hotel['ville'])?> · <?=str_repeat('★',(int)$hotel['etoiles'])?> <?php if($hotel['note']):?> · ★ <?=e($hotel['note'])?>/5<?php endif;?></p></div></section><div class="container"><div class="detail-gallery"><?php for($i=0;$i<3;$i++):?><div><?php if(!empty($photos[$i]['fichier'])):?><img src="<?=e(BASE_URL.'/uploads/hotels/'.$photos[$i]['fichier'])?>" alt="Photo de <?=e($hotel['nom'])?>"><?php else:?><span class="muted">HotelConnect</span><?php endif;?></div><?php endfor;?></div><div class="detail-content"><div><section class="panel"><h2>À propos de cet établissement</h2><p><?=nl2br(e($hotel['description']?:'Bienvenue dans cet établissement. Contactez l’hôtel pour plus d’informations.'))?></p><p class="muted">Arrivée : <?=e(substr($hotel['heure_arrivee'],0,5))?> · Départ : <?=e(substr($hotel['heure_depart'],0,5))?></p></section><section class="panel"><h2>Équipements et services</h2><div class="amenity-list"><?php foreach($amenities as $a):?><span><?=e($a['nom'])?></span><?php endforeach;?><?php if(!$amenities):?><span>Informations à venir</span><?php endif;?></div></section><section class="panel"><h2>Chambres disponibles à la réservation</h2><?php foreach($rooms as $r):?><div class="d-flex justify-content-between align-items-center gap-3 py-3 border-bottom"><div><strong><?=e($r['nom'])?></strong><p class="muted mb-1"><?=e($r['type'])?> · <?=e($r['capacite'])?> personne(s)</p><small class="muted"><?=e($r['description']??'')?></small></div><div class="text-end"><strong><?=money($r['prix_nuit'])?></strong><small class="d-block muted">par nuit</small><a class="btn btn-primary mt-2" href="<?=BASE_URL?>/book.php?room=<?=$r['id']?>">Réserver</a></div></div><?php endforeach;?><?php if(!$rooms):?><p class="muted">Aucune chambre publiée pour le moment.</p><?php endif;?></section><section class="panel"><h2>Avis des voyageurs</h2><?php foreach($reviews as $rv):?><div class="py-3 border-bottom"><strong><?=e($rv['prenom'])?></strong> <span class="text-warning">★ <?=e($rv['note'])?>/5</span><p class="mb-1 mt-2"><?=e($rv['commentaire'])?></p><?php if($rv['reponse']):?><p class="muted">Réponse de l’hôtel : <?=e($rv['reponse'])?></p><?php endif;?></div><?php endforeach;?><?php if(!$reviews):?><p class="muted">Pas encore d’avis.</p><?php endif;?></section></div><aside class="booking-box"><span class="eyebrow">VOTRE SÉJOUR</span><h3 class="h5">Un séjour en toute simplicité</h3><p class="muted">Consultez les chambres et choisissez vos dates pour effectuer une demande de réservation.</p><?php if($rooms):?><strong class="price"><?=money(min(array_column($rooms,'prix_nuit')))?></strong><span class="muted"> / nuit à partir de</span><a class="btn btn-primary d-block mt-3" href="#">Choisir une chambre ↓</a><?php endif;?><hr><p class="mb-1"><strong>Contact</strong></p><p class="muted mb-1"><?=e($hotel['telephone']?:'Téléphone non renseigné')?></p><p class="muted"><?=e($hotel['email']?:'Email non renseigné')?></p></aside></div></div><?php require __DIR__.'/includes/footer.php';?>